-- Errata reading for O01: Last six months = event_date 2029-02-16..2029-08-15 (as-of minus 6 months, exclusive start), matching the trailing-window convention C3 used by every 12-month reference (2028-08-16..2029-08-15) and O02 (2029-02-16..).
WITH r AS MATERIALIZED (SELECT patient, stream, payload FROM records WHERE stream IN ('conditions','pharmacy_dispenses')), hf AS (SELECT DISTINCT patient FROM r WHERE stream='conditions' AND (lower(json_extract(payload,'$.description')) LIKE '%heart failure%' OR coalesce(json_extract(payload,'$.icd10'),'') LIKE 'I50%')), fx AS (SELECT DISTINCT patient FROM r WHERE stream='pharmacy_dispenses' AND lower(json_extract(payload,'$.medication_name')) LIKE '%furosemide%' AND json_extract(payload,'$.status')='dispensed' AND json_extract(payload,'$.event_date') BETWEEN '2029-02-16' AND '2029-08-15') SELECT COUNT(*) AS count FROM hf JOIN fx USING(patient);
